import {ownRecord,denseValues} from './state-validation.mjs';
export const argumentActivity={id:'arguments',stage:'12y',key:'12y:arguments',area:'Pensamiento crítico',type:'digital',label:'13–18 años',kind:'interactive',title:'Construir y revisar un argumento',unit:'La sala de dibujo: datos y decisiones',copy:'Relaciona una afirmación con registros ficticios. Revisa qué cambia cuando aparece otra explicación y distingue una conclusión de una decisión.',goal:'Construir un argumento, reconocer sus límites y comparar una revisión sin evaluar opiniones personales.',duration:'A tu ritmo · puedes parar en cualquier paso',support:'Ayuda lectora disponible; también puedes señalar o trabajar en papel',transfer:'En papel, dibuja tres cajas: afirmación, dato y límite. Usa otro caso inventado y explica qué información podría hacerte revisar la conclusión. No hace falta contar experiencias personales.'};
export const argumentClaims={open:'Estos registros no bastan para aislar el efecto del horario.',count:'En la segunda semana registrada hubo más visitas.',cause:'Ampliar el horario causó el aumento de visitas.',everyone:'Todo el alumnado prefiere ampliar el horario.'};
export const argumentEvidence={count:{title:'Registro de entradas',kind:'Recuento ficticio',text:'Cinco días antes: 12 visitas. Cinco días con 30 minutos más de apertura: 18 visitas. Se cuentan entradas, no personas distintas.'},opinion:{title:'Una frase del comité',kind:'Opinión ficticia',text:'«La sala abierta más tiempo nos parece una buena idea». Es una valoración; no un recuento de uso ni una encuesta al alumnado.'},poster:{title:'El anuncio del piloto',kind:'Promesa ficticia',text:'«Con más horario, todas las personas dibujarán más». El anuncio no aporta datos sobre quiénes usarán la sala.'},event:{title:'La agenda que faltaba',kind:'Nueva información ficticia',text:'La segunda semana también hubo un taller especial de ilustración. No sabemos cuántas de las 18 entradas estuvieron relacionadas con él.'}};
export const argumentLimits={scope:'El registro describe solo esos días y cuenta visitas, no personas.',alternatives:'Podrían haber cambiado otras condiciones además del horario.',voices:'No conocemos las preferencias de todo el alumnado.'};
export const argumentPriorities={access:'Facilitar distintos horarios de acceso',resources:'Revisar los recursos de apertura'};
export const argumentDecisions={trial:'Proponer otro piloto acotado',review:'Pedir más información antes de ampliar'};
export const argumentNextData={repeat:'Comparar semanas semejantes sin taller especial',people:'Distinguir visitas repetidas de personas distintas con recuentos agregados',access:'Examinar franjas de acceso que no se observaron'};
const nextDataMeaning={repeat:'Ayudaría a separar explicaciones alternativas; una comparación nueva también necesita revisar sus condiciones.',people:'Aclararía el alcance del uso, pero no demostraría por sí sola una causa.',access:'Aportaría información para la decisión de acceso, no una prueba de que el horario causó el aumento.'};
export const newArgument=()=>({page:0,claim:null,evidence:[],limit:null,priority:null,decision:null,nextData:null,reviewed:false,hint:false,original:null});
const option=(value,options,nullable=true)=>{if(!(nullable&&value===null)&&!(typeof value==='string'&&Object.hasOwn(options,value)))throw Error('Invalid option');return value;};
function draft(raw,allowEvent){ownRecord(raw,['claim','evidence','limit']);const evidence=denseValues(raw.evidence,allowEvent?['count','opinion','poster','event']:['count','opinion','poster'],4);if(new Set(evidence).size!==evidence.length)throw Error('Repeated evidence');return {claim:option(raw.claim,argumentClaims),evidence,limit:option(raw.limit,argumentLimits)};}
export function validateArgument(raw){
 ownRecord(raw,['page','claim','evidence','limit','priority','decision','nextData','reviewed','hint','original']);
 if(!Number.isInteger(raw.page)||raw.page<0||raw.page>2||typeof raw.reviewed!=='boolean'||typeof raw.hint!=='boolean')throw Error('Invalid argument');
 const d=draft({claim:raw.claim,evidence:raw.evidence,limit:raw.limit},raw.page>0),original=raw.original===null?null:draft(raw.original,false);
 option(raw.priority,argumentPriorities);option(raw.decision,argumentDecisions);option(raw.nextData,argumentNextData);
 if(raw.page===0&&(original||raw.priority!==null||raw.decision!==null||raw.nextData!==null)||raw.page>0&&(!original||!original.claim||!original.evidence.length||!original.limit)||raw.page===2&&(!d.claim||!d.evidence.length||!d.limit||!raw.priority||!raw.decision||!raw.nextData||!raw.reviewed))throw Error('Invalid argument step');
 return {...raw,...d,original};
}
export function analyzeArgument(s){
 const notes=[];let supported=false;
 if(!s.claim||!s.evidence.length)notes.push('Elige una afirmación y vincula al menos una tarjeta para revisar la relación.');
 else if(s.claim==='count'&&s.evidence.includes('count')){supported=true;notes.push('El recuento respalda que hubo más visitas en esos días: 18 frente a 12. No identifica personas distintas ni una causa.');}
 else if(s.claim==='count')notes.push('Esta afirmación necesita el recuento. Una opinión o un anuncio no muestran cuántas entradas hubo.');
 else if(s.claim==='open'){supported=s.evidence.includes('count')||s.page>0&&s.evidence.includes('event');notes.push(s.page>0&&s.evidence.includes('event')?'La agenda aporta otra condición que cambió a la vez: el taller especial. Basta para justificar que estos registros no aíslan el efecto del horario; no demuestra cuánto influyó cada condición.':supported?'El registro compara dos semanas, pero no separa las posibles condiciones que cambiaron. Dejar la causa abierta está justificado; no significa negar las visitas observadas.':'Vincula el recuento para mostrar qué se comparó y qué no quedó controlado.');}
 else if(s.claim==='cause')notes.push(s.page>0?'El taller especial coincide con el cambio de horario. Hay otra explicación posible: estos registros no separan sus efectos.':'Observar un aumento después del cambio no basta para atribuirle una causa. Falta comparar otras condiciones.');
 else notes.push('Contar visitas no informa de las preferencias de todo el alumnado. Tampoco la opinión del comité o el anuncio permiten afirmarlo.');
 if(s.evidence.includes('opinion'))notes.push('La frase del comité es una valoración. Puede motivar una decisión, pero no sustituye una medida de uso.');
 if(s.evidence.includes('poster'))notes.push('El anuncio expresa una promesa sin datos propios. Vincularlo no convierte la promesa en evidencia.');
 if(s.limit)notes.push('Límite elegido: '+argumentLimits[s.limit]+(!['count','open'].includes(s.claim)?' Añadir un límite no corrige por sí solo una afirmación demasiado amplia.':''));
 return {supported,notes};
}
export function advanceArgument(s){
 if(!s.claim||!s.evidence.length||!s.limit||!s.reviewed||s.page===2)return false;
 if(s.page===0){s.original={claim:s.claim,evidence:denseValues(s.evidence,['count','opinion','poster'],3),limit:s.limit};s.page=1;s.reviewed=false;s.hint=false;return true;}
 if(!s.priority||!s.decision||!s.nextData)return false;s.page=2;s.hint=false;return true;
}
export function decisionExplanation(s){
 if(!s.priority||!s.decision)return 'La recomendación queda pendiente. Elegir una acción no demuestra una causa.';
 if(s.decision==='trial')return s.priority==='access'?'Este comité propondría un piloto con horarios alternos y compararía quién podría acceder a cada franja. Es una propuesta, no una conclusión demostrada por las cifras.':'Este comité propondría un piloto limitado y revisaría qué recursos necesita antes de prolongarlo. Las cifras de visitas no resuelven esa prioridad.';
 return s.priority==='access'?'Este comité pediría información sobre franjas de acceso que faltan antes de ampliar. No supone que quienes no entraron rechacen la sala.':'Este comité pediría un plan de recursos y registros comparables antes de ampliar. Eso deja abierta la decisión, sin negar el aumento observado.';
}
export function renderArguments(root,st,{finish}){
 const s=st.argument??=newArgument(),analysis=analyzeArgument(s),ready=!!(s.claim&&s.evidence.length&&s.limit&&s.reviewed&&(s.page===0||s.priority&&s.decision&&s.nextData));
 const redraw=id=>{renderArguments(root,st,{finish});root.querySelector(id)?.focus();};
 const choices=(data,selected,attr)=>`<div class="argument-choices">${Object.entries(data).map(([id,label])=>`<button type="button" class="action secondary" ${attr}="${id}" aria-pressed="${selected===id}">${label}</button>`).join('')}</div>`;
 const map=d=>`<div class="argument-map"><div><strong>Afirmación</strong><p>${d.claim?argumentClaims[d.claim]:'Por elegir'}</p></div><span aria-hidden="true">←</span><div><strong>Tarjetas vinculadas</strong><p>${d.evidence.length?d.evidence.map(id=>argumentEvidence[id].title).join(' · '):'Ninguna todavía'}</p></div><span aria-hidden="true">＋</span><div><strong>Límite</strong><p>${d.limit?argumentLimits[d.limit]:'Por elegir'}</p></div></div>`;
 const hint=s.page===0?'Separa recuento, opinión y promesa. Pregunta qué frase puede sostener la tarjeta por sí sola. Puedes cambiar cualquiera de las tres partes del tablero.':'La agenda añade otra condición que cambió. Puedes mantener una descripción limitada del recuento y revisar la causa. Una prioridad del comité orienta una acción, no prueba un hecho.';
 root.innerHTML=`<section class="argument-studio" aria-labelledby="argument-title"><p class="eyebrow">13–18 años · caso íntegramente ficticio</p><h4 id="argument-title" tabindex="-1">La sala de dibujo: datos y decisiones</h4><p>Un comité imaginario estudia ampliar el horario de una sala. Construye su argumento; no pedimos tus opiniones personales ni experiencias.</p><ol class="construction-steps" aria-label="Recorrido"><li ${s.page===0?'aria-current="step"':''}>Construir un borrador</li><li ${s.page===1?'aria-current="step"':''}>Revisar con información nueva</li><li ${s.page===2?'aria-current="step"':''}>Comparar y cerrar</li></ol>${s.page>0?'<aside class="notice"><strong>Una condición nueva:</strong> la agenda revela que también hubo un taller especial. El aumento sigue registrado, pero atribuirlo solo al horario requiere más información.</aside>':''}${s.page<2?`<h5>Registros para explorar</h5><p>Vincula o retira tarjetas. Después revisa si sostienen la afirmación; no todas cumplen la misma función.</p><div class="argument-evidence">${Object.entries(argumentEvidence).filter(([id])=>id!=='event'||s.page>0).map(([id,e])=>`<button type="button" class="argument-card" data-argument-evidence="${id}" aria-pressed="${s.evidence.includes(id)}"><span class="pill">${e.kind}</span><strong>${e.title}</strong><span>${e.text}</span>${id==='count'?'<span class="argument-bars" aria-hidden="true"><i class="argument-bar-before"></i><i class="argument-bar-after"></i></span>':''}<span class="argument-linked">${s.evidence.includes(id)?'Vinculada al argumento':'Vincular esta tarjeta'}</span></button>`).join('')}</div><fieldset><legend>Afirmación del borrador</legend>${choices(argumentClaims,s.claim,'data-argument-claim')}</fieldset><fieldset><legend>Un límite que conviene explicitar</legend>${choices(argumentLimits,s.limit,'data-argument-limit')}</fieldset><h5>Tu tablero de relaciones</h5>${map(s)}<div class="controls"><button type="button" class="action primary" id="argument-review">Revisar las relaciones</button><button type="button" class="action secondary" id="argument-hint">Una pista para este paso</button></div><div id="argument-feedback" role="status" tabindex="-1">${s.reviewed?`<strong>${analysis.supported?'Conclusión acotada respaldada por el registro':'Relación pendiente de justificar'}</strong>${analysis.notes.map(x=>`<p>${x}</p>`).join('')}`:''}</div><p id="argument-hint-text" role="status" tabindex="-1">${s.hint?hint:''}</p>${s.page===1?`<fieldset><legend>Una prioridad del comité ficticio</legend><p>Esto es un criterio para decidir, no un dato sobre visitas ni una pregunta sobre tus valores.</p>${choices(argumentPriorities,s.priority,'data-argument-priority')}</fieldset><fieldset><legend>Una recomendación posible</legend>${choices(argumentDecisions,s.decision,'data-argument-decision')}</fieldset><p id="argument-decision-text" role="status">${decisionExplanation(s)}</p><fieldset><legend>¿Qué información buscaría después este comité ficticio?</legend>${choices(argumentNextData,s.nextData,'data-argument-nextdata')}</fieldset><p role="status">${s.nextData?nextDataMeaning[s.nextData]:''}</p>`:''}<p>${ready?'Puedes seguir con este borrador, incluso si hay relaciones pendientes. También puedes revisarlo o parar.':'Elige afirmación, tarjetas y límite; revisa las relaciones.'+(s.page===1?' Añade una prioridad del comité, una recomendación y el siguiente dato para comparar.':'')}</p><button type="button" class="action primary" id="argument-next" ${ready?'':'disabled'}>${s.page===0?'Abrir la información que faltaba':'Comparar los dos borradores'}</button>`:`<h5>Primer borrador</h5>${map(s.original)}<h5>Versión revisada</h5>${map(s)}<div class="notice"><strong>${analysis.supported?'La conclusión acotada se apoya en el registro':'Este borrador mantiene una relación pendiente de justificar'}</strong>${analysis.notes.map(x=>`<p>${x}</p>`).join('')}</div><p><strong>Prioridad del comité:</strong> ${argumentPriorities[s.priority]}.</p><p><strong>Recomendación:</strong> ${argumentDecisions[s.decision]}.</p><p>${decisionExplanation(s)}</p><p><strong>Información que falta:</strong> ${argumentNextData[s.nextData]}. ${nextDataMeaning[s.nextData]}</p><p>Una conclusión describe lo que los registros permiten sostener. Una recomendación también depende de prioridades y de información que falta; no hay una única decisión obligatoria.</p><p><strong>Fuera de pantalla:</strong> dibuja tres cajas —afirmación, dato y límite— para otro caso inventado. Señala qué información podría cambiar la conclusión. No hace falta contar experiencias ni escribir opiniones personales.</p><div class="controls"><button type="button" class="action secondary" id="argument-revise">Probar otra revisión</button><button type="button" class="action primary" id="argument-finish">Terminar por hoy</button></div>`}<p class="quiet">Puedes pausar, salir o pedir ayuda arriba. No hay puntuación ni un perfil de tus ideas.</p></section>`;
 const on=(id,fn)=>{const el=root.querySelector('#'+id);if(el)el.onclick=fn;};
 for(const key of ['claim','limit','priority','decision','nextdata'])root.querySelectorAll(`[data-argument-${key}]`).forEach(el=>el.onclick=()=>{const field=key==='nextdata'?'nextData':key;s[field]=el.getAttribute('data-argument-'+key);if(key==='claim'||key==='limit')s.reviewed=false;redraw(`[data-argument-${key}="${s[field]}"]`);});
 root.querySelectorAll('[data-argument-evidence]').forEach(el=>el.onclick=()=>{const id=el.dataset.argumentEvidence;s.evidence=s.evidence.includes(id)?s.evidence.filter(x=>x!==id):s.evidence.concat(id);s.reviewed=false;redraw(`[data-argument-evidence="${id}"]`);});
 on('argument-review',()=>{s.reviewed=true;redraw('#argument-feedback');});
 on('argument-hint',()=>{s.hint=true;redraw('#argument-hint-text');});
 on('argument-next',()=>{if(advanceArgument(s))redraw('#argument-title');});
 on('argument-revise',()=>{s.page=1;s.reviewed=false;redraw('#argument-title');});
 on('argument-finish',finish);
}
